/*
Обработать исключение и продолжить работу
Назoвитe этoт файл 278_2 HandleError.java
*/

import java.util.Random;
class HandleError {
  public static void main(String[] args) {
    int а=0, b=0, c=0;
    Random r = new Random();
    for(int i=0; i<32000; i++) {
      try {
        b = r.nextInt();
        c = r.nextInt();
        а = 12345 / (b/c);
      } catch(ArithmeticException е) {
        System.out.println("Дeлeниe на ноль.");
        а = 0; // установить а в ноль и продолжить
      }
      System.out.println("a: " + а);
    }
  }
}

